# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TÜRKİSTAN\'DAN TÜRKİYE\'YE BİLİM VE DÜŞÜNCE ÖNCÜLERİ (TAR.10.1.4)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">DİL, TARİH, ASTRONOMİ VE MÜHENDİSLİK</text>\n  <text x="35" y="88" font-size="11" fill="#1e3a8a">• Kaşgarlı Mahmud: Dîvânu Lugâti\'t-Türk (İlk Türkçe</text>\n  <text x="35" y="105" font-size="11" fill="#1e3a8a">  ansiklopedik sözlük ve Türk dünyası haritası)</text>\n  <text x="35" y="125" font-size="11" fill="#1e3a8a">• Ömer Hayyam: İsfahan Rasathanesi, Celâlî Takvimi ve Cebir</text>\n  <text x="35" y="145" font-size="11" fill="#1e3a8a">• El-Cezerî (Artuklu): Kitâbü\'l-Hiyel (Sibernetik ve robotik</text>\n  <text x="35" y="162" font-size="11" fill="#1e3a8a">  öncüsü; su saatleri, krank mili, otomatik makineler)</text>\n  <text x="35" y="182" font-size="11" fill="#1e3a8a">• İbn Bîbî: el-Evâmirü\'l-Alâiyye (Türkiye Selçuklu tarihi)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">HORASAN VE ANADOLU GÖNÜL ERENLERİ (TASAVVUF)</text>\n  <text x="370" y="88" font-size="11" fill="#14532d">• Hoca Ahmed Yesevî (Pîr-i Türkistan): Dîvân-ı Hikmet</text>\n  <text x="370" y="108" font-size="11" fill="#14532d">• Muhyiddîn İbnü\'l-Arabî: Vahdet-i vücûd düşüncesi</text>\n  <text x="370" y="128" font-size="11" fill="#14532d">• Mevlânâ Celâleddîn-i Rûmî: Mesnevî, Fîhi Mâ Fîh</text>\n  <text x="370" y="148" font-size="11" fill="#14532d">• Hacı Bektâş-ı Velî: Makâlât (Sulucakarahöyük dergâhı)</text>\n  <text x="370" y="168" font-size="11" fill="#14532d">• Yunus Emre: Risâletü\'n-Nushiyye ve Dîvân (Arı Türkçe)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«Sevelim, sevilelim, dünya kimseye kalmaz.» (Yunus Emre) — Gönüllerin fethiyle Anadolu vatanlaşmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ANADOLU\'NUN TÜRKLEŞMESİ VE İSLAMLAŞMASINDA KURUMLAR VE SANAT</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">AHİLİK TEŞKİLATI VE BACIYÂN-I RÛM</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Kurucusu: Ahi Evran (Nasîrüddin Mahmud) — Kırşehir</text>\n  <text x="35" y="108" font-size="11.2" fill="#713f12">• Ahlaki Nizamname: Fütüvvetnâme (Elini, sofranı,</text>\n  <text x="35" y="126" font-size="11.2" fill="#713f12">  kapını açık tut; gözünü, dilini, belini bağlı tut)</text>\n  <text x="35" y="146" font-size="11.2" fill="#713f12">• Mesleki Eğitim: Yamak → Çırak → Kalfa → Usta (Şed)</text>\n  <text x="35" y="166" font-size="11.2" fill="#713f12">• Bacıyân-ı Rûm (Anadolu Bacıları): Fatma Bacı öncülüğü</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">EĞİTİM, SAĞLIK VE MİMARİ ESERLER</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Medreseler: Yağıbasan (Tokat/Niksar), Cacabey (Kırşehir),</text>\n  <text x="370" y="106" font-size="11.2" fill="#581c87">  Karatay ve İnce Minareli (Konya), Çifte Minareli (Erzurum)</text>\n  <text x="370" y="126" font-size="11.2" fill="#581c87">• Darüşşifalar: Gevher Nesibe (Kayseri, 1206 — ilk tıp</text>\n  <text x="370" y="144" font-size="11.2" fill="#581c87">  okulu), Divriği Ulu Camii ve Darüşşifası (Mengücekliler)</text>\n  <text x="370" y="166" font-size="11.2" fill="#581c87">• Sanat: Taş-ahşap işçiliği, çini, halı, minyatür ve hat</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kılıçla fethedilen Anadolu; alimlerin ilmi, erenlerin irfanı, Ahilerin iş ahlakı ve vakıf eserleriyle vatan olmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1. ÜNİTE ÖZETİ: TÜRKİSTAN\'DAN TÜRKİYE\'YE (1040 - 1299) KRONOLOJİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">SİYASİ VE ASKERÎ DÖNÜM NOKTALARI</text>\n  <text x="35" y="88" font-size="11" fill="#7c2d12">• 1040 Dandanakan: Büyük Selçuklu Devleti\'nin kuruluşu</text>\n  <text x="35" y="106" font-size="11" fill="#7c2d12">• 1048 Pasinler: Bizans\'la ilk büyük Selçuklu zaferi</text>\n  <text x="35" y="124" font-size="11" fill="#7c2d12">• 1071 Malazgirt: Anadolu\'nun kapılarının Türklere açılması</text>\n  <text x="35" y="142" font-size="11" fill="#7c2d12">• 1077 Türkiye Selçuklu Devleti ve I. Dönem Beylikler</text>\n  <text x="35" y="160" font-size="11" fill="#7c2d12">• 1176 Miryokefalon: Anadolu\'nun kesin Türk yurdu oluşu</text>\n  <text x="35" y="178" font-size="11" fill="#7c2d12">• 1243 Kösedağ: Moğol tahakkümü ve II. Dönem Beylikler</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">DEVLET, ORDU VE SOSYOEKONOMİK YAPI</text>\n  <text x="370" y="88" font-size="11" fill="#164e63">• Yönetim: Kut anlayışı, Divan-ı Saltanat, Atabeylik sistemi</text>\n  <text x="370" y="108" font-size="11" fill="#164e63">• Ordu ve Toprak: Gulam sistemi, İkta sistemi ve Sipahiler</text>\n  <text x="370" y="128" font-size="11" fill="#164e63">• Ticaret: Kervansaraylar (Ribât), devlet sigortası, limanlar</text>\n  <text x="370" y="148" font-size="11" fill="#164e63">• Bilim Kurumu: Nizamiye Medreseleri ve Anadolu medreseleri</text>\n  <text x="370" y="168" font-size="11" font-weight="bold" fill="#155e75">• 1299: Uç beyliğinden cihan devletine — Osmanlı kuruluşu</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">1040-1299 süreci; Türklerin Oğuz göçleriyle Anadolu\'yu fethedip kalıcı bir Türk-İslam medeniyeti kurduğu devirdir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
